    /// The icon a project or workspace names (a lucide component name, as stored in config).
    init?(componentName: String) {
        switch componentName {
        case "Folder": self = .folder
        case "FolderGit2": self = .folderGit2
        case "Code": self = .code
        case "Globe": self = .globe
        case "Database": self = .database
        case "Server": self = .server
        case "Smartphone": self = .smartphone
        case "Package": self = .package
        case "FileCode": self = .fileCode
        case "Terminal": self = .terminal
        case "Cpu": self = .cpu
        case "Cloud": self = .cloud
        case "Shield": self = .shield
        case "Zap": self = .zap
        case "Workflow": self = .workflow
        case "Gamepad2": self = .gamepad2
        case "Music": self = .music
        case "Image": self = .image
        case "BookOpen": self = .bookOpen
        case "FlaskConical": self = .flaskConical
        case "Rocket": self = .rocket
        case "Play": self = .play
        case "User": self = .user
        case "Briefcase": self = .briefcase
        case "Home": self = .house
        case "House": self = .house
        case "Building2": self = .building2
        case "Heart": self = .heart
        case "Star": self = .star
        case "Sparkles": self = .sparkles
        case "Layers": self = .layers
        default: return nil
        }
    }
